CREATE TABLE characters (id uuid PRIMARY KEY, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE character_configs (character_id uuid NOT NULL REFERENCES characters(id), version bigint NOT NULL CHECK(version>=0), schema_version int NOT NULL CHECK(schema_version=1), preset_id text NOT NULL, domain_version text NOT NULL, provider_config_version text NOT NULL, body jsonb NOT NULL CHECK(jsonb_typeof(body)='object'), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(character_id,version));
CREATE TABLE identities (id uuid PRIMARY KEY, platform text NOT NULL CHECK(platform IN ('local_test','local_operator')), platform_subject_id text NOT NULL, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(platform,platform_subject_id));
CREATE TABLE sessions (id uuid PRIMARY KEY, character_id uuid NOT NULL REFERENCES characters(id), config_version bigint NOT NULL, status text NOT NULL CHECK(status IN ('active','ending','ended','interrupted')), visibility text NOT NULL CHECK(visibility='test_public'), started_at timestamptz NOT NULL, ended_at timestamptz, last_user_input_at timestamptz, last_output_end_at timestamptz, output_epoch bigint NOT NULL DEFAULT 0 CHECK(output_epoch>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), FOREIGN KEY(character_id,config_version) REFERENCES character_configs(character_id,version), CHECK((status IN ('active','ending') AND ended_at IS NULL) OR (status IN ('ended','interrupted') AND ended_at IS NOT NULL)));
CREATE UNIQUE INDEX sessions_one_open_uq ON sessions(character_id) WHERE status IN ('active','ending');
CREATE TABLE events (id uuid PRIMARY KEY, character_id uuid NOT NULL, session_id uuid NOT NULL, identity_id uuid REFERENCES identities(id), parent_event_id uuid, source_namespace text NOT NULL CHECK(length(source_namespace)>0), source_key text NOT NULL CHECK(length(source_key)>0), kind text NOT NULL, occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL, observed_at timestamptz, applied_at timestamptz, attention_status text NOT NULL CHECK(attention_status IN ('pending','selected','observed','ignored','expired')), data_status text NOT NULL CHECK(data_status IN ('active','superseded','deleted')), revision bigint NOT NULL CHECK(revision>=0), schema_version int NOT NULL CHECK(schema_version=1), payload jsonb, superseded_by_event_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,session_id,id), UNIQUE(character_id,source_namespace,source_key), FOREIGN KEY(character_id,session_id) REFERENCES sessions(character_id,id), FOREIGN KEY(character_id,parent_event_id) REFERENCES events(character_id,id), FOREIGN KEY(character_id,superseded_by_event_id) REFERENCES events(character_id,id), CHECK((data_status='deleted' AND payload IS NULL) OR (data_status<>'deleted' AND payload IS NOT NULL)));
CREATE INDEX events_timeline_idx ON events(character_id,session_id,received_at DESC,id DESC);
CREATE TABLE appraisals (id uuid PRIMARY KEY, character_id uuid NOT NULL, event_id uuid NOT NULL, event_revision bigint NOT NULL CHECK(event_revision>=0), request_id uuid NOT NULL UNIQUE, generation_epoch bigint NOT NULL CHECK(generation_epoch>=0), config_version bigint NOT NULL, provider text NOT NULL, model text NOT NULL, model_digest text, prompt_version text NOT NULL, status text NOT NULL CHECK(status IN ('running','accepted','stale','cancelled','failed','timed_out')), result jsonb, context_refs jsonb NOT NULL, failure_code text, latency_ms int CHECK(latency_ms>=0), usage jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), FOREIGN KEY(character_id,event_id) REFERENCES events(character_id,id), FOREIGN KEY(character_id,config_version) REFERENCES character_configs(character_id,version), CHECK(status<>'accepted' OR result IS NOT NULL));
CREATE UNIQUE INDEX appraisals_one_accepted_uq ON appraisals(character_id,event_id,event_revision) WHERE status='accepted';
CREATE FUNCTION valid_state(body jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE k text; e jsonb; v double precision; item jsonb;
BEGIN
 IF jsonb_typeof(body) IS DISTINCT FROM 'object' OR NOT body ?& ARRAY['affect','mood','attention','workingMemoryEventIds','expression','turn'] THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY['joy','frustration','surprise','embarrassment'] LOOP
  e:=body->'affect'->k;
  IF e IS NULL OR jsonb_typeof(e->'value') IS DISTINCT FROM 'number' OR jsonb_typeof(e->'asOf') IS DISTINCT FROM 'number' OR jsonb_typeof(e->'holdUntil') IS DISTINCT FROM 'number' OR jsonb_typeof(e->'causes') IS DISTINCT FROM 'array' OR jsonb_array_length(e->'causes')>20 THEN RETURN false; END IF;
  v:=(e->>'value')::double precision;
  IF NOT (v>=0 AND v<=1) OR (e->>'asOf')::double precision<0 OR (e->>'holdUntil')::double precision<0 THEN RETURN false; END IF;
 END LOOP;
 IF jsonb_typeof(body->'mood'->'pleasantness') IS DISTINCT FROM 'number' OR jsonb_typeof(body->'mood'->'asOf') IS DISTINCT FROM 'number' THEN RETURN false; END IF;
 v:=(body->'mood'->>'pleasantness')::double precision;
 IF NOT(v>=0 AND v<=1) OR (body->'mood'->>'asOf')::double precision<0 OR jsonb_typeof(body->'workingMemoryEventIds') IS DISTINCT FROM 'array' OR jsonb_array_length(body->'workingMemoryEventIds')>20 THEN RETURN false; END IF;
 IF jsonb_typeof(body->'attention') IS DISTINCT FROM 'object' OR NOT (body->'attention') ?& ARRAY['eventId','lastIdentityId','consecutive'] OR jsonb_typeof(body->'attention'->'consecutive') IS DISTINCT FROM 'number' THEN RETURN false; END IF;
 v:=(body->'attention'->>'consecutive')::double precision;
 IF v<0 OR v<>trunc(v) OR jsonb_typeof(body->'expression') IS DISTINCT FROM 'object' OR (body->'expression'->>'kind') IS NULL OR (body->'expression'->>'kind') NOT IN ('neutral','listening','happy','embarrassed','uncomfortable') OR jsonb_typeof(body->'expression'->'since') IS DISTINCT FROM 'number' OR (body->'expression'->>'since')::double precision<0 THEN RETURN false; END IF;
 IF jsonb_typeof(body->'turn') IS DISTINCT FROM 'object' OR jsonb_typeof(body->'turn'->'listening') IS DISTINCT FROM 'boolean' OR jsonb_typeof(body->'turn'->'acknowledgements') IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_each(body->'turn'->'acknowledgements') LOOP IF jsonb_typeof(item) IS DISTINCT FROM 'number' OR (item #>> '{}')::double precision<0 THEN RETURN false; END IF; END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(body->'workingMemoryEventIds') LOOP PERFORM (item #>> '{}')::uuid; END LOOP;
 IF (body->'attention'->>'eventId') IS NOT NULL THEN PERFORM (body->'attention'->>'eventId')::uuid; END IF;
 IF (body->'attention'->>'lastIdentityId') IS NOT NULL THEN PERFORM (body->'attention'->>'lastIdentityId')::uuid; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE TABLE character_state (character_id uuid PRIMARY KEY REFERENCES characters(id), version bigint NOT NULL CHECK(version>=0), config_version bigint NOT NULL, schema_version int NOT NULL CHECK(schema_version=1), generation_epoch bigint NOT NULL CHECK(generation_epoch>=0), snapshot_at timestamptz NOT NULL, body jsonb NOT NULL CHECK(valid_state(body)), FOREIGN KEY(character_id,config_version) REFERENCES character_configs(character_id,version));
CREATE TABLE transitions (id uuid PRIMARY KEY, character_id uuid NOT NULL, source_event_id uuid NOT NULL, appraisal_id uuid, state_version bigint NOT NULL CHECK(state_version>=0), config_version bigint NOT NULL, core_version text NOT NULL, evaluated_at timestamptz NOT NULL, effects jsonb, replay_status text NOT NULL CHECK(replay_status IN ('available','source_redacted')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,source_event_id), UNIQUE(character_id,state_version), FOREIGN KEY(character_id,source_event_id) REFERENCES events(character_id,id), FOREIGN KEY(character_id,appraisal_id) REFERENCES appraisals(character_id,id), FOREIGN KEY(character_id,config_version) REFERENCES character_configs(character_id,version));
CREATE TABLE response_runs (id uuid PRIMARY KEY, character_id uuid NOT NULL, session_id uuid NOT NULL, trigger_event_id uuid NOT NULL, generation_epoch bigint NOT NULL CHECK(generation_epoch>=0), config_version bigint NOT NULL, status text NOT NULL CHECK(status IN ('planned','generating','synthesizing','delivering','completed','cancelled','failed','interrupted')), plan jsonb, segment_count int CHECK(segment_count BETWEEN 1 AND 2), deadline_at timestamptz NOT NULL, cancel_reason text, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(character_id,session_id,id), FOREIGN KEY(character_id,session_id,trigger_event_id) REFERENCES events(character_id,session_id,id), FOREIGN KEY(character_id,config_version) REFERENCES character_configs(character_id,version));
CREATE UNIQUE INDEX responses_one_active_uq ON response_runs(character_id) WHERE status IN ('planned','generating','synthesizing','delivering');
CREATE TABLE response_sources (id uuid PRIMARY KEY, character_id uuid NOT NULL, response_id uuid NOT NULL, event_id uuid, memory_id uuid, source_version bigint NOT NULL CHECK(source_version>=0), FOREIGN KEY(character_id,response_id) REFERENCES response_runs(character_id,id), FOREIGN KEY(character_id,event_id) REFERENCES events(character_id,id), CHECK((event_id IS NULL)<>(memory_id IS NULL)));
CREATE UNIQUE INDEX response_sources_event_uq ON response_sources(response_id,event_id) WHERE event_id IS NOT NULL;
CREATE UNIQUE INDEX response_sources_memory_uq ON response_sources(response_id,memory_id) WHERE memory_id IS NOT NULL;
CREATE INDEX response_sources_event_idx ON response_sources(character_id,event_id,response_id) WHERE event_id IS NOT NULL;
CREATE INDEX response_sources_memory_idx ON response_sources(character_id,memory_id,response_id) WHERE memory_id IS NOT NULL;
CREATE TABLE speech_segments (id uuid PRIMARY KEY, character_id uuid NOT NULL, response_id uuid NOT NULL, segment_index int NOT NULL CHECK(segment_index BETWEEN 0 AND 1), text text, synthesis_status text NOT NULL CHECK(synthesis_status IN ('pending','running','ready','failed','cancelled')), delivery_status text NOT NULL CHECK(delivery_status IN ('not_sent','sent','playing','finished','cancelled','unknown')), duration_ms int CHECK(duration_ms BETWEEN 0 AND 20000), played_ms int NOT NULL DEFAULT 0 CHECK(played_ms>=0), output_epoch bigint CHECK(output_epoch>=0), playback_client_id uuid, text_shown_at timestamptz, audio_started_at timestamptz, audio_completed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(character_id,id), UNIQUE(response_id,segment_index), FOREIGN KEY(character_id,response_id) REFERENCES response_runs(character_id,id), CHECK(duration_ms IS NULL OR played_ms<=duration_ms));
